<?php $rows=$pdo->query('SELECT mh.*,m.name mechanic_name,u.unit_code FROM mechanic_hours mh JOIN mechanics m ON m.id=mh.mechanic_id LEFT JOIN units u ON u.id=mh.unit_id ORDER BY work_date DESC')->fetchAll();$mechs=$pdo->query('SELECT * FROM mechanics WHERE is_active=1 ORDER BY name')->fetchAll();$units=$pdo->query('SELECT id,unit_code FROM units ORDER BY unit_code')->fetchAll();?>
<div class="card panel"><h3>Input Jam Kerja Aktual Mekanik</h3><form class="form-grid compact" method="post" action="actions/save_mechanic_hours.php"><input type="hidden" name="_csrf" value="<?=csrf_token()?>"><label>Mekanik<select name="mechanic_id"><?php foreach($mechs as $m):?><option value="<?=$m['id']?>"><?=e($m['name'])?></option><?php endforeach;?></select></label><label>Tanggal<input type="date" name="work_date" value="<?=date('Y-m-d')?>"></label><label>Unit<select name="unit_id"><option value="">Non-unit</option><?php foreach($units as $u):?><option value="<?=$u['id']?>"><?=e($u['unit_code'])?></option><?php endforeach;?></select></label><label>Work Order<input name="work_order_no"></label><label>Jam Mulai<input type="time" name="start_time"></label><label>Jam Selesai<input type="time" name="end_time"></label><label>Jam Efektif<input type="number" step="0.25" name="effective_hours"></label><label>Aktivitas<input name="activity"></label><div><button class="btn primary">Simpan</button></div></form></div>
<div class="card panel"><h3>Jam Kerja Riil</h3><table><thead><tr><th>Tanggal</th><th>Mekanik</th><th>Unit</th><th>WO</th><th>Mulai</th><th>Selesai</th><th>Efektif</th><th>Aktivitas</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['work_date'])?></td><td><?=e($r['mechanic_name'])?></td><td><?=e($r['unit_code']??'-')?></td><td><?=e($r['work_order_no'])?></td><td><?=e($r['start_time'])?></td><td><?=e($r['end_time'])?></td><td><?=$r['effective_hours']?> jam</td><td><?=e($r['activity'])?></td></tr><?php endforeach;?></tbody></table></div>
